(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.RationalLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function tex(q){return num.fractionTex(num.rational(q.n,q.d));}
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);}
function tick(n,left,top){const e=document.createElement('span');e.className='transform-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#rational-ticks').append(e);}
for(let n=-5;n<=5;n++){const p=core.point(n,n);svg('line',{x1:p.x,x2:p.x,y1:30,y2:330},$('#rational-grid'));svg('line',{x1:30,x2:330,y1:p.y,y2:p.y},$('#rational-grid'));tick(n,p.x/3.6,53);if(n!==0)tick(n,47,p.y/3.6);}
const formulas={hole:'f(x)=\\frac{x^2-1}{x-1}=x+1,\\quad x\\ne1',pole:'f(x)=\\frac{x+1}{x-1}=1+\\frac2{x-1}',partial:'f(x)=\\frac{x^2-1}{(x-1)^2}=\\frac{x+1}{x-1},\\quad x\\ne1'};
function draw(){const kind=$('[name="rational-case"]:checked').value,index=Number($('#proximity').value),hole=kind==='hole';const commands=[];for(const [lo,hi] of [[-5,.998],[1.002,5]])for(let i=0;i<=400;i++){const x=lo+(hi-lo)*i/400,p=core.point(x,core.value(kind,x));commands.push(`${i===0?'M':'L'}${p.x} ${p.y}`);}$('#rational-curve').setAttribute('d',commands.join(' '));$('#asymptote-lines').setAttribute('d',hole?'':'M210 30V330 M30 150H330');$('#rational-markers').replaceChildren();for(const [side,id] of [[-1,'sample-left'],[1,'sample-right']]){const s=core.sample(kind,index,side);math($('#'+id),`f\\left(${tex(s.x)}\\right)=${tex(s.y)}`);const p=core.point(s.x.n/s.x.d,s.y.n/s.y.d);if(p.x>=30&&p.x<=330&&p.y>=30&&p.y<=330)svg('circle',{cx:p.x,cy:p.y,r:3.5,fill:'#b4754f',stroke:'white','stroke-width':1},$('#rational-markers'));}if(hole)svg('circle',{cx:210,cy:120,r:5,fill:'#fafaf5',stroke:'#244d40','stroke-width':2},$('#rational-markers'));math($('#rational-equation'),formulas[kind]);math($('#distance-output'),`\\frac1{${core.denominators[index]}}`);math($('#rational-sets'),`D=\\mathbb R\\setminus\\{1\\},\\qquad R_f=\\mathbb R\\setminus\\{${hole?2:1}\\}`);$('#rational-feedback').textContent=hole?'Faktor penyebab nol pada penyebut hilang seluruhnya. Grafik sama dengan garis yang bersesuaian, kecuali lubang pada koordinat mendatar satu dan tegak dua.':kind==='partial'?'Pembilang dan penyebut sama-sama nol pada satu, tetapi setelah satu faktor dicoret masih tersisa faktor penyebab nol di penyebut. Ada asimtot tegak, bukan lubang.':'Penyebut nol pada satu dan pembilang tidak nol. Ada asimtot tegak pada masukan satu serta asimtot mendatar pada keluaran satu.';$('#sample-feedback').textContent=hole?'Kedua nilai makin dekat dua ketika jaraknya diperkecil. Nilai di kiri sedikit di bawah dua dan nilai di kanan sedikit di atas dua. Nilai tepat pada satu tetap tidak terdefinisi.':'Ketika jarak diperkecil, nilai dari kiri menjadi negatif dengan besar yang makin meningkat; nilai dari kanan menjadi positif dengan besar yang makin meningkat. Titik yang keluar dari jendela tetap ditampilkan nilainya pada kartu.';$('#rational-plot').setAttribute('aria-label',hole?'Garis dengan lubang di titik (1, 2). Dua sampel masukan berada di kedua sisi satu.':'Dua cabang fungsi rasional dengan asimtot tegak x sama dengan satu dan asimtot mendatar y sama dengan satu. Cabang grafik tidak dihubungkan melintasi masukan yang dilarang.');$('#forbidden-feedback').textContent='';}
document.querySelectorAll('[name="rational-case"]').forEach(e=>e.addEventListener('change',draw));$('#proximity').addEventListener('input',draw);$('#try-forbidden').addEventListener('click',()=>{$('#forbidden-feedback').textContent='Tidak terdefinisi. Pada ketiga bentuk awal, masukan satu membuat penyebut nol. Mendekati nilai itu tidak membuatnya menjadi anggota domain.';});draw();
const questions=[{tex:'f(x)=\\frac{x+2}{x-3}',prompt:'Nilai masukan berapa yang harus dikecualikan dari domain real terbesar?',n:3,hint:'Cari masukan yang membuat penyebut nol.',why:'Penyebut nol pada masukan tiga. Pembilang nol pada negatif dua tetap boleh karena penyebutnya tidak nol.'},{tex:'f(x)=\\frac{x^2-4}{x-2}',prompt:'Grafik mempunyai lubang pada koordinat mendatar dua. Berapa koordinat tegak lubangnya?',n:4,hint:'Faktorkan pembilang dan sederhanakan untuk masukan selain dua.',why:'Bentuk sederhana adalah masukan ditambah dua, sehingga grafik mendekati koordinat tegak empat saat masukan mendekati dua. Titik itu tetap dikecualikan.'},{tex:'f(x)=\\frac{2x+1}{x-1}',prompt:'Berapa nilai keluaran yang menjadi asimtot mendatar?',n:2,hint:'Derajat pembilang dan penyebut sama. Bandingkan koefisien utamanya.',why:'Koefisien utama pembilang dua dan penyebut satu. Hasil baginya dua, sehingga asimtot mendatarnya pada keluaran dua.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 3.':'Belum tepat. Periksa penyebut awal, hasil faktorisasi, atau koefisien utama sesuai pertanyaannya.');}));
const choices=[{tex:'f(x)=\\frac{x^2-1}{(x-1)^2}',prompt:'Apa yang terjadi pada masukan satu?',options:['Ada lubang karena pembilang dan penyebut sama-sama nol.','Ada asimtot tegak karena penyebut yang tersisa masih nol.','Fungsinya bernilai dua setelah faktor dicoret.'],answer:1,why:'Setelah satu faktor dicoret, masih tersisa masukan dikurangi satu pada penyebut. Nilainya tumbuh tanpa batas saat mendekati masukan terlarang.'},{tex:'f(x)=\\frac{x^2-1}{x-1}',prompt:'Apa akar real fungsi semula?',options:['Hanya negatif satu.','Negatif satu dan satu.','Hanya satu.'],answer:0,why:'Negatif satu berada dalam domain dan menghasilkan nol. Masukan satu dilarang, sehingga bukan akar fungsi semula.'},{tex:'f(x)=\\frac{x}{x^2+1}',prompt:'Fungsi ini mempunyai asimtot mendatar pada keluaran nol. Pernyataan mana yang benar?',options:['Grafik tidak mungkin mencapai keluaran nol.','Masukan nol harus dilarang dari domain.','Grafik dapat melewati titik asal walaupun mempunyai asimtot mendatar nol.'],answer:2,why:'Pada masukan nol, penyebut satu dan keluaran nol. Asimtot mendatar menjelaskan perilaku jauh di ujung, bukan larangan perpotongan di tengah.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-rational-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-rational-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();